// src/pages/Auth.js
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { authAPI } from '../services/api';
import { Btn, Field, Spinner } from '../components/UI';

function AuthBox({ children }) {
  return (
    <div style={{
      minHeight: '100vh', display: 'flex', alignItems: 'center',
      justifyContent: 'center', background: 'var(--bv-bg)', padding: 16,
    }}>
      <div style={{
        width: '100%', maxWidth: 400,
        background: 'var(--bv-bg2)', border: '1px solid var(--bv-bd)',
        borderRadius: 12, overflow: 'hidden',
      }}>
        <div style={{ padding: '24px 28px 0', textAlign: 'center', borderBottom: '1px solid var(--bv-bd)', paddingBottom: 20 }}>
          <div style={{
            width: 44, height: 44, background: 'linear-gradient(135deg,var(--bv-accent),var(--bv-accent-dark))',
            borderRadius: 10, display: 'flex', alignItems: 'center',
            justifyContent: 'center', margin: '0 auto 12px',
            fontSize: 18, fontWeight: 700, color: '#fff',
          }}>BV</div>
          <div style={{ fontSize: 18, fontWeight: 600, color: 'var(--bv-txt)' }}>BackupVault</div>
          <div style={{ fontSize: 12, color: 'var(--bv-cyan)', marginTop: 3 }}>Database Manager</div>
        </div>
        <div style={{ padding: '24px 28px 28px' }}>{children}</div>
      </div>
    </div>
  );
}

export function LoginPage() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [view, setView] = useState('login'); // login | forgot | otp | reset
  const [forgotEmail, setForgotEmail] = useState('');
  const [otpData, setOtpData] = useState({ otp: '', newPassword: '', confirm: '' });
  const [msg, setMsg] = useState('');
  const { login } = useAuth();
  const navigate = useNavigate();

  async function handleLogin(e) {
    e.preventDefault();
    setError(''); setLoading(true);
    try {
      await login(form.email, form.password);
      navigate('/dashboard');
    } catch (err) {
      setError(err.message);
    } finally { setLoading(false); }
  }

  async function handleForgot(e) {
    e.preventDefault();
    setLoading(true); setError(''); setMsg('');
    try {
      await authAPI.forgot(forgotEmail);
      setMsg('If the account exists, an OTP has been sent.');
      setView('otp');
    } catch (err) { setError(err.message); }
    finally { setLoading(false); }
  }

  async function handleReset(e) {
    e.preventDefault();
    if (otpData.newPassword !== otpData.confirm) return setError('Passwords do not match');
    setLoading(true); setError('');
    try {
      await authAPI.reset(forgotEmail, otpData.otp, otpData.newPassword);
      setMsg('Password reset successful. Please log in.');
      setView('login');
    } catch (err) { setError(err.message); }
    finally { setLoading(false); }
  }

  if (view === 'forgot') return (
    <AuthBox>
      <h3 style={{ marginBottom: 20, fontSize: 15 }}>Forgot Password</h3>
      <form onSubmit={handleForgot}>
        <Field label="Email address" required>
          <input type="email" value={forgotEmail} onChange={e => setForgotEmail(e.target.value)} placeholder="admin@worktual.tech" style={{ width: '100%' }} required />
        </Field>
        {error && <div style={{ color: 'var(--bv-red)', fontSize: 12, marginBottom: 12 }}>{error}</div>}
        {msg && <div style={{ color: 'var(--bv-green)', fontSize: 12, marginBottom: 12 }}>{msg}</div>}
        <Btn variant="primary" loading={loading} style={{ width: '100%', justifyContent: 'center' }}>Send OTP</Btn>
        <button type="button" onClick={() => setView('login')} style={{ background: 'none', border: 'none', color: 'var(--bv-blue)', fontSize: 12, marginTop: 12, width: '100%' }}>Back to login</button>
      </form>
    </AuthBox>
  );

  if (view === 'otp') return (
    <AuthBox>
      <h3 style={{ marginBottom: 6, fontSize: 15 }}>Enter OTP</h3>
      <p style={{ fontSize: 12, color: 'var(--bv-txt2)', marginBottom: 20 }}>Check your email for a 6-digit verification code.</p>
      <form onSubmit={handleReset}>
        <Field label="OTP Code" required>
          <input value={otpData.otp} onChange={e => setOtpData(p => ({ ...p, otp: e.target.value }))} placeholder="123456" style={{ width: '100%' }} maxLength={6} required />
        </Field>
        <Field label="New Password" required>
          <input type="password" value={otpData.newPassword} onChange={e => setOtpData(p => ({ ...p, newPassword: e.target.value }))} style={{ width: '100%' }} required minLength={8} />
        </Field>
        <Field label="Confirm Password" required>
          <input type="password" value={otpData.confirm} onChange={e => setOtpData(p => ({ ...p, confirm: e.target.value }))} style={{ width: '100%' }} required />
        </Field>
        {error && <div style={{ color: 'var(--bv-red)', fontSize: 12, marginBottom: 12 }}>{error}</div>}
        <Btn variant="primary" loading={loading} style={{ width: '100%', justifyContent: 'center' }}>Reset Password</Btn>
        <button type="button" onClick={() => setView('login')} style={{ background: 'none', border: 'none', color: 'var(--bv-blue)', fontSize: 12, marginTop: 12, width: '100%' }}>Back to login</button>
      </form>
    </AuthBox>
  );

  return (
    <AuthBox>
      <h3 style={{ marginBottom: 20, fontSize: 15 }}>Sign In</h3>
      <form onSubmit={handleLogin}>
        <Field label="Email address" required>
          <input type="email" value={form.email} onChange={e => setForm(p => ({ ...p, email: e.target.value }))} placeholder="admin@worktual.tech" style={{ width: '100%' }} required />
        </Field>
        <Field label="Password" required>
          <input type="password" value={form.password} onChange={e => setForm(p => ({ ...p, password: e.target.value }))} style={{ width: '100%' }} required />
        </Field>
        {msg && <div style={{ color: 'var(--bv-green)', fontSize: 12, marginBottom: 12 }}>{msg}</div>}
        {error && <div style={{ color: 'var(--bv-red)', fontSize: 12, marginBottom: 12 }}>{error}</div>}
        <Btn variant="primary" loading={loading} style={{ width: '100%', justifyContent: 'center', marginBottom: 12 }}>Sign In</Btn>
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12 }}>
          <button type="button" onClick={() => { setView('forgot'); setError(''); setMsg(''); }} style={{ background: 'none', border: 'none', color: 'var(--bv-blue)' }}>Forgot password?</button>
          <a href="/register" style={{ color: 'var(--bv-blue)' }}>Create account</a>
        </div>
      </form>
    </AuthBox>
  );
}

export function RegisterPage() {
  const [form, setForm] = useState({ name: '', email: '', password: '', confirm: '' });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const navigate = useNavigate();

  async function handleRegister(e) {
    e.preventDefault();
    if (form.password !== form.confirm) return setError('Passwords do not match');
    setError(''); setLoading(true);
    try {
      await authAPI.register(form.name, form.email, form.password);
      setSuccess('Account created. Redirecting to login...');
      setTimeout(() => navigate('/login'), 2000);
    } catch (err) { setError(err.message); }
    finally { setLoading(false); }
  }

  return (
    <AuthBox>
      <h3 style={{ marginBottom: 20, fontSize: 15 }}>Create Admin Account</h3>
      <form onSubmit={handleRegister}>
        <Field label="Full Name" required>
          <input value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))} placeholder="Admin Name" style={{ width: '100%' }} required />
        </Field>
        <Field label="Email address" required>
          <input type="email" value={form.email} onChange={e => setForm(p => ({ ...p, email: e.target.value }))} placeholder="admin@worktual.tech" style={{ width: '100%' }} required />
        </Field>
        <Field label="Password" required hint="Minimum 8 characters">
          <input type="password" value={form.password} onChange={e => setForm(p => ({ ...p, password: e.target.value }))} style={{ width: '100%' }} required minLength={8} />
        </Field>
        <Field label="Confirm Password" required>
          <input type="password" value={form.confirm} onChange={e => setForm(p => ({ ...p, confirm: e.target.value }))} style={{ width: '100%' }} required />
        </Field>
        {error && <div style={{ color: 'var(--bv-red)', fontSize: 12, marginBottom: 12 }}>{error}</div>}
        {success && <div style={{ color: 'var(--bv-green)', fontSize: 12, marginBottom: 12 }}>{success}</div>}
        <Btn variant="primary" loading={loading} style={{ width: '100%', justifyContent: 'center', marginBottom: 12 }}>Create Account</Btn>
        <a href="/login" style={{ display: 'block', textAlign: 'center', fontSize: 12, color: 'var(--bv-blue)' }}>Already have an account? Sign in</a>
      </form>
    </AuthBox>
  );
}
